// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        uint256 pre = c.currentDifficulty();
        bool ok;
        vm.prank(caller);
        try c.AdjustDifficulty(amount) { ok = true; } catch { ok = false; }
        if (caller == address(this)) {
            assertTrue(ok && c.currentDifficulty() == amount);
        } else {
            assertTrue((!ok) && c.currentDifficulty() == pre);
        }
    }
}
